/// <summary>
/// This class extends the CustCustomerDetailV2Entity data entity
/// </summary>
[ExtensionOf(tableStr(CustCustomerDetailV2Entity))]
internal final class METCustCustomerDetailV2Entity_Extension
{
}

Method.Source:
/// <summary>
/// This method maps data from the data entity to the data source.
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerDetailV2Entity, METBusinessUnit))
    {
        DataEntityDataSourceRuntimeContext dataSourceContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(CustCustomerDetailV2Entity, METBusinessUnit));
        if (dataSourceContext)
        {
            if (this.METBusinessName)
            {
                METBusinessUnit businessUnit;

                select firstonly businessUnit
                    where businessUnit.BusinessName == this.METBusinessName
                    &&    businessUnit.BusinessPrefix == this.METBusinessPrefix;

                dataSourceContext.setBuffer(businessUnit);
            }

            dataSourceContext.setDataSaved(true);
            dataSourceContext.setDatabaseOperation(DataEntityDatabaseOperation::None);
        }
    }

    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(CustCustomerDetailV2Entity, CustTable))
    {
        CustTable custTable = _dataSourceCtx.getBuffer();
        if (this.WarehouseId)
        {
            custTable.InventLocation = this.WarehouseId;
            custTable.InventSiteId = InventLocation::find(this.WarehouseId).InventSiteId;

            custTable.DefaultDimension = InventSite::changeDimension(custTable.DefaultDimension, custTable.InventSiteId);
        }
    }

    if (_dataSourceCtx.name() != dataEntityDataSourceStr(CustCustomerDetailV2Entity, CustTable))
    {
        this.metSaveOtherTables(_dataSourceCtx);
    }

}

private void metSaveOtherTables(DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    switch(_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(CustCustomerDetailV2Entity, METCustTableEntity):
            if (this.CustomerAccount)
            {
                METCustTable metCustTable = METCustTable::find(this.CustomerAccount, true);

                if (metCustTable.RecId)
                {
                    metCustTable.IndustryKey = this.MetIndustryKey;

                    if (metCustTable.validateWrite())
                    {
                        metCustTable.update();
                    }
                    else
                    {
                        throw error(strFmt('@MET:ValidateSubsidiaryHazard', tableStr(METCustTable)));
                    }
                }
                else
                {
                    metCustTable.AccountNum = this.CustomerAccount;
                    metCustTable.IndustryKey = this.MetIndustryKey;

                    if (metCustTable.validateWrite())
                    {
                        metCustTable.insert();
                    }
                    else
                    {
                        throw error(strFmt('@MET:ValidateSubsidiaryHazard', tableStr(METCustTable)));
                    }
                }
            }
            break;
    }

    _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
    _dataSourceCtx.setDataSaved(true);
}
